package com.travelbird.ai.controller;
import com.travelbird.ai.dto.request.*;import com.travelbird.ai.dto.response.*;import com.travelbird.ai.service.AiPreviewService;import com.travelbird.auth.security.AuthenticatedUser;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai/trip-previews") public class AiPreviewController{private final AiPreviewService service;public AiPreviewController(AiPreviewService s){service=s;}@GetMapping("/{previewId}")public AiPreviewResponse get(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long previewId){return service.get(u.userId(),previewId);}@PatchMapping("/{previewId}")public AiPreviewResponse update(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long previewId,@RequestBody UpdateAiTripPreviewRequest r){return service.update(u.userId(),previewId,r);}@PostMapping("/{previewId}/apply")public ApplyAiPreviewResponse apply(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long previewId){return service.apply(u.userId(),previewId);}}
